-- Placements fonciers : terrain à bâtir et terrain agricole, ajoutés au réglage `invest` s'il est déjà enregistré.
UPDATE game_setting SET value = jsonb_set(value, '{options}', (value->'options') || $j$[{"id": "terre_adidogome", "kind": "FARM", "emoji": "🏞️", "nameFr": "Terrain à bâtir (Adidogomé)", "nameEn": "Building plot (Adidogomé)", "descFr": "Tu achètes un terrain, tu le gardes, puis tu le revends quand le quartier se construit. 60 jours.", "descEn": "Buy a plot, hold it, then resell as the area gets built up. 60 days.", "cost": 500000, "gameDays": 60, "minReturnBp": 1000, "maxReturnBp": 5000, "failBp": 600}, {"id": "terre_plateaux", "kind": "FARM", "emoji": "🌳", "nameFr": "Terrain agricole (Plateaux, 2 ha)", "nameEn": "Farmland (Plateaux, 2 ha)", "descFr": "Achat de terres cultivables à revendre ou à louer. Valeur qui monte lentement. 90 jours.", "descEn": "Buy arable land to resell or lease. Value rises slowly. 90 days.", "cost": 300000, "gameDays": 90, "minReturnBp": 800, "maxReturnBp": 4000, "failBp": 500}]$j$::jsonb)
WHERE key = 'invest' AND NOT (value->'options') @> '[{"id": "terre_adidogome"}]'::jsonb;
